#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('.')
p = root / 'src/eval.rs'
s = p.read_text()
anchor = '''        let mut cur = e;\n        while rem != 0 {\n'''
insert = '''        let mut cur = e;\n\n        // v27: the post-incumbent census shows that the dominant cold-prune\n        // shape is exactly one Cons cell followed by an already materialized\n        // Framed environment.  Specialize that structural case without adding\n        // a new representation or cache: preserve the normal intern_frame key,\n        // materialized slots, and cache publication semantics.\n        if let value::Env::Cons { v, parent, .. } = e {\n            if let value::Env::Framed { mask: fmask, slots, .. } = *parent {\n                if rem & 1 != 0 {\n                    buf[n].write(*v);\n                    slots_hash = slots_hash\n                        .wrapping_mul(0x9E3779B97F4A7C15)\n                        .wrapping_add(*v as *const Value<'t> as usize as u64);\n                    out_mask |= 1;\n                    n += 1;\n                }\n                let rem1 = rem >> 1;\n                if rem1 != 0 {\n                    // consumed == 1, so only source positions 0..62 can map\n                    // back into the 64-bit output mask after the left shift.\n                    let m2 = rem1 & *fmask & (u64::MAX >> 1);\n                    out_mask |= m2 << 1;\n                    let mut sel = select_ranks(m2, *fmask);\n                    while sel != 0 {\n                        let i = sel.trailing_zeros() as usize;\n                        sel &= sel - 1;\n                        let sv = slots[i];\n                        buf[n].write(sv);\n                        slots_hash = slots_hash\n                            .wrapping_mul(0x9E3779B97F4A7C15)\n                            .wrapping_add(sv as *const Value<'t> as usize as u64);\n                        n += 1;\n                    }\n                }\n                let selected: &[V<'t>] = unsafe {\n                    std::slice::from_raw_parts(buf.as_ptr().cast::<V<'t>>(), n)\n                };\n                let lsub = e.lsub();\n                let hash = out_mask\n                    .wrapping_mul(0x9E3779B97F4A7C15)\n                    .wrapping_add(slots_hash);\n                let r = self.intern_frame(hash, out_mask, selected, lsub);\n                self.tc_cache.prune_dm[slot] =\n                    (e as *const value::Env<'t> as usize, mask, Some(r));\n                if let value::Env::Cons { prune, .. } = e {\n                    prune.set((mask, Some(r)));\n                }\n                return r;\n            }\n        }\n\n        while rem != 0 {\n'''
assert s.count(anchor) == 1, s.count(anchor)
p.write_text(s.replace(anchor, insert, 1))
print('V27_ONE_CONS_FRAMED_FASTPATH_PATCH=APPLIED')
